import { beforeEach, describe, expect, it, vi } from 'vitest';
import cssBlockingPlugin from '../../plugins/cssBlockingPlugin.js';
const CSS_CASES = [
    '.css',
    '.less',
    '.sass',
    '.scss',
    '.styl',
    '.stylus',
    '.sss',
];
describe('cssBlockingPlugin', () => {
    describe('metadata', () => {
        it('should have the correct plugin name', () => {
            const plugin = cssBlockingPlugin();
            expect(plugin.name).toBe('ui-extensions-css-blocking-plugin');
        });
        it('should enforce pre', () => {
            const plugin = cssBlockingPlugin();
            expect(plugin.enforce).toBe('pre');
        });
    });
    describe('resolveId', () => {
        const callResolveId = (plugin, id, importer) => plugin.resolveId(id, importer);
        describe('remote build mode (no logger — strict)', () => {
            let plugin;
            let onCssBlockedSpy;
            beforeEach(() => {
                onCssBlockedSpy = vi.fn();
                plugin = cssBlockingPlugin({ onCssBlocked: onCssBlockedSpy });
            });
            it.each(CSS_CASES)('should call onCssBlocked for %s imports from customer source', (ext) => {
                callResolveId(plugin, `styles${ext}`, '/customer/src/app.tsx');
                expect(onCssBlockedSpy).toHaveBeenCalledWith(expect.stringContaining('CSS is not supported'));
            });
            it('should include the import path in the blocked message', () => {
                callResolveId(plugin, './theme.scss', '/customer/src/app.tsx');
                expect(onCssBlockedSpy).toHaveBeenCalledWith(expect.stringContaining("Remove the import of './theme.scss' from your extension."));
            });
            it('should return the virtual module id so the build can complete', () => {
                const result = callResolveId(plugin, 'styles.scss', '/customer/src/app.tsx');
                expect(result).toBe('\0ui-ext-css-blocked');
            });
            it.each(CSS_CASES)('should silently block %s imports when importer is in node_modules', (ext) => {
                const result = callResolveId(plugin, `styles${ext}`, '/customer/node_modules/some-lib/index.js');
                expect(onCssBlockedSpy).not.toHaveBeenCalled();
                expect(result).toBe('\0ui-ext-css-blocked');
            });
            it.each(['styles.scss?inline', 'styles.css?url', 'styles.less?raw'])('should call onCssBlocked for %s (query-string bypass attempt)', (id) => {
                callResolveId(plugin, id, '/customer/src/app.tsx');
                expect(onCssBlockedSpy).toHaveBeenCalledWith(expect.stringContaining('CSS is not supported'));
            });
        });
        describe('dev mode (with logger — warn only)', () => {
            let plugin;
            let warnSpy;
            beforeEach(() => {
                warnSpy = vi.fn();
                plugin = cssBlockingPlugin({
                    logger: {
                        info: vi.fn(),
                        debug: vi.fn(),
                        warn: warnSpy,
                        error: vi.fn(),
                    },
                });
            });
            it.each(CSS_CASES)('should warn (not throw) for %s imports from customer source', (ext) => {
                expect(() => callResolveId(plugin, `styles${ext}`, '/customer/src/app.tsx')).not.toThrow();
                expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining('CSS is not supported'));
            });
            it('should include WARNING: prefix and import path in the warning message', () => {
                callResolveId(plugin, './theme.scss', '/customer/src/app.tsx');
                expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining('WARNING:'));
                expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("Remove the import of './theme.scss'"));
            });
            it('should return a virtual module id after warning so Vite stops processing the CSS', () => {
                const result = callResolveId(plugin, 'styles.scss', '/customer/src/app.tsx');
                expect(result).toBe('\0ui-ext-css-blocked');
            });
            it.each(CSS_CASES)('should silently block %s imports when importer is in node_modules', (ext) => {
                const result = callResolveId(plugin, `styles${ext}`, '/customer/node_modules/some-lib/index.js');
                expect(warnSpy).not.toHaveBeenCalled();
                expect(result).toBe('\0ui-ext-css-blocked');
            });
        });
        describe('load hook', () => {
            it('should return empty string for the virtual blocked-css module id', () => {
                const plugin = cssBlockingPlugin();
                const load = plugin.load;
                expect(load('\0ui-ext-css-blocked')).toBe('');
            });
            it('should return null for non-blocked module ids', () => {
                const plugin = cssBlockingPlugin();
                const load = plugin.load;
                expect(load('./utils.ts')).toBeNull();
            });
        });
        describe('non-CSS imports', () => {
            let plugin;
            beforeEach(() => {
                plugin = cssBlockingPlugin();
            });
            it('should return null for .ts imports', () => {
                expect(callResolveId(plugin, './utils.ts', '/customer/src/app.tsx')).toBeNull();
            });
            it('should return null for .tsx imports', () => {
                expect(callResolveId(plugin, './App.tsx', '/customer/src/app.tsx')).toBeNull();
            });
            it('should return null for imports with no extension', () => {
                expect(callResolveId(plugin, 'some-package', '/customer/src/app.tsx')).toBeNull();
            });
            it('should return null for non-CSS imports from node_modules', () => {
                expect(callResolveId(plugin, './index.js', '/customer/node_modules/some-lib/index.js')).toBeNull();
            });
        });
    });
});
